CREATE FUNCTION `get_quota`(_id VARCHAR(16)
) RETURNS longtext CHARSET utf8mb4 COLLATE utf8mb4_bin
    DETERMINISTIC
BEGIN 
  DECLARE _uid VARCHAR(16);
  DECLARE _domain_id INTEGER;
  DECLARE _quota_json JSON;
  DECLARE _res JSON;

  
  SELECT id, domain_id
  FROM drumate 
    WHERE id=_id OR email=_id 
    INTO _uid, _domain_id;

  
  IF _uid IS NULL THEN
    SET _domain_id = 1;

    SELECT quota 
    FROM quota 
    WHERE payer_id = 'ffffffffffffffff' AND domain_id = 1
    LIMIT 1
    INTO _quota_json;
    
    
    IF _quota_json IS NOT NULL THEN
      RETURN JSON_SET(
        _quota_json,
        '$.domain_id', 1,
        '$.category', JSON_VALUE(_quota_json, '$.plan')
      );
    ELSE
      RETURN NULL;
    END IF;
  END IF;

  
  SELECT quota 
  FROM quota 
  WHERE payer_id = _uid 
  LIMIT 1
  INTO _quota_json;
  
  
  IF _quota_json IS NULL AND _domain_id > 1 THEN
    SELECT quota 
    FROM quota 
    WHERE domain_id = _domain_id 
    LIMIT 1
    INTO _quota_json;
  END IF;
  
  
  IF _quota_json IS NULL THEN
    SELECT quota 
    FROM quota 
    WHERE payer_id = 'ffffffffffffffff' AND domain_id = 1
    LIMIT 1
    INTO _quota_json;
  END IF;

  IF _quota_json IS NOT NULL THEN
    
    RETURN JSON_SET(
      _quota_json,
      '$.domain_id', _domain_id,
      '$.category', JSON_VALUE(_quota_json, '$.plan')
    );
  ELSE
    
    RETURN NULL;
  END IF;
END ;;
DELIMITER ;
