) RETURNS varchar(1024) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    DETERMINISTIC
BEGIN
  DECLARE _r INTEGER DEFAULT 0;
  SELECT COUNT(*) FROM socket s 
