CREATE FUNCTION `uniqueId`() RETURNS varchar(16) CHARSET ascii COLLATE ascii_general_ci
    DETERMINISTIC
BEGIN
  DECLARE _res VARCHAR(16);
  SELECT CONCAT(
    SUBSTRING_INDEX(UUID(), '-', 1),
    SUBSTRING_INDEX(UUID(), '-', 1)
  ) INTO _res;
  RETURN _res;
END ;;
