CREATE PROCEDURE `dmz_remove_media`(
  IN _id      VARCHAR(16) CHARACTER SET ascii
 
)
BEGIN
 SELECT * FROM dmz_media WHERE id = _id;
 DELETE FROM dmz_media WHERE id = _id;
END ;;
