CREATE PROCEDURE `domains_list`(
  IN _args JSON
)
BEGIN
  DECLARE _range bigint;
  DECLARE _offset bigint;
  DECLARE _column VARCHAR(20) DEFAULT 'name';
  DECLARE _order VARCHAR(20) DEFAULT 'asc';
  DECLARE _type VARCHAR(20) DEFAULT NULL;
  DECLARE _domain VARCHAR(20) DEFAULT NULL;
  DECLARE _page INTEGER DEFAULT 1;

  SELECT JSON_VALUE(_args, "$.domain") INTO _domain;
  CALL pageToLimits(_page, _offset, _range);

  DROP TABLE IF EXISTS _uploads;
  CREATE TEMPORARY TABLE _uploads AS 
    SELECT uid id, max(timestamp) ctime FROM mfs_changelog WHERE event='media.new' GROUP BY uid;

  DROP TABLE IF EXISTS _domains;
  CREATE TEMPORARY TABLE `_domains` (
    `email` varchar(128) NOT NULL,
    `username` varchar(128) DEFAULT NULL,
    `domain` varchar(128) DEFAULT NULL,
    PRIMARY KEY (`email`)
  );
  INSERT IGNORE INTO _domains SELECT 
    d.email, 
    SUBSTRING_INDEX(d.email, '@', 1) AS username,
    SUBSTRING_INDEX(d.email, '@', -1) AS domain 
  FROM drumate d 
    INNER JOIN _uploads USING(id);

  SELECT count(*) count, domain name FROM _domains WHERE 
    IF(_domain IS NULL, 1, domain LIKE CONCAT("%", _domain, "%")) AND
    domain NOT IN (SELECT domain FROM providers) GROUP BY domain ORDER BY count DESC, name ASC
    LIMIT _offset, _range;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
