CREATE PROCEDURE `domain_details`(
  IN _args JSON
)
BEGIN
  DECLARE _column VARCHAR(20) DEFAULT 'name';
  DECLARE _order VARCHAR(20) DEFAULT 'asc';
  DECLARE _type VARCHAR(20) DEFAULT NULL;
  DECLARE _hub_id VARCHAR(20) DEFAULT NULL;
  DECLARE _domain VARCHAR(520) DEFAULT NULL;
  DECLARE _db_name VARCHAR(520) DEFAULT NULL;
  DECLARE _finished INTEGER DEFAULT 0;
  DECLARE _domains_count INTEGER UNSIGNED;
  DECLARE dbcursor CURSOR FOR SELECT db_name, hub_id, type FROM _domains;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET _finished = 1; 

  SELECT IFNULL(JSON_VALUE(_args, "$.domain"), 'date') INTO _domain;

  DROP TABLE IF EXISTS _domains;
  CREATE TEMPORARY TABLE `_domains` (
    `db_name` varchar(128) NOT NULL,
    `hub_id` varchar(28) NOT NULL,
    `email` varchar(128) NOT NULL,
    `area` varchar(12) NOT NULL,
    `type` varchar(12) NOT NULL,
    PRIMARY KEY (`db_name`)
  );

  DROP TABLE IF EXISTS _files;
  CREATE TEMPORARY TABLE `_files` (
    `c` INTEGER UNSIGNED,
    `filesize` BIGINT(20) unsigned DEFAULT 0
  );

  INSERT IGNORE INTO _domains SELECT 
    db_name,
    d.id, 
    d.email,
    e.area,
    e.type
  FROM drumate d 
    INNER JOIN entity e ON e.id=d.id
    WHERE SUBSTRING_INDEX(d.email, '@', -1)=_domain;


  INSERT IGNORE INTO _domains SELECT 
    e.db_name,
    e.id, 
    d.email,
    e.area,
    e.type
  FROM hub h
    INNER JOIN entity e ON e.id=h.id
    INNER JOIN _domains d ON h.owner_id=d.hub_id
    WHERE SUBSTRING_INDEX(d.email, '@', -1)=_domain;


  DROP TABLE IF EXISTS _files;
  CREATE TEMPORARY TABLE `_files` (
    `hub_id` varchar(128) NOT NULL,
    `nid` varchar(128) NOT NULL,
    `category` varchar(128) NOT NULL,
    `extension` varchar(128) NOT NULL,
    `user_filename` varchar(128) NOT NULL,
    `filesize` varchar(128) NOT NULL,
    PRIMARY KEY (`hub_id`, `nid`)
  );

  DROP TABLE IF EXISTS _chats;
  CREATE TEMPORARY TABLE `_chats` (
    `hub_id` varchar(128) NOT NULL,
    `message_id` varchar(128) NOT NULL,
    `attachment` varchar(128) NOT NULL,
    PRIMARY KEY (`message_id`)
  );

  DROP TABLE IF EXISTS _contacts;
  CREATE TEMPORARY TABLE `_contacts` (
    `hub_id` varchar(128) NOT NULL,
    `id` varchar(128) NOT NULL,
    `category` varchar(128) NOT NULL,
    PRIMARY KEY (`id`)
  );
  
  OPEN dbcursor;
   STARTLOOP: LOOP
    FETCH dbcursor INTO _db_name, _hub_id, _type;
    IF _finished = 1 THEN 
      LEAVE STARTLOOP;
    END IF;
     
    SET @s = CONCAT("INSERT IGNORE INTO _files SELECT ", 
      QUOTE(_hub_id), 
      ", id",
      ", category",
      ", extension",
      ", user_filename",
      ", filesize FROM ",
      _db_name,
      ".media"
      );
    PREPARE stmt FROM @s;
    EXECUTE stmt ;
    DEALLOCATE PREPARE stmt;

     
    SET @s = CONCAT("INSERT IGNORE INTO _chats SELECT ", 
      QUOTE(_hub_id), 
      ", message_id",
      ", attachment FROM ",
      _db_name,
      ".channel"
      );
    PREPARE stmt FROM @s;
    EXECUTE stmt ;
    DEALLOCATE PREPARE stmt;

    IF _type = 'drumate' THEN 
      
      SET @s = CONCAT("INSERT IGNORE INTO _contacts SELECT ", 
        QUOTE(_hub_id), 
        ", entity",
        ", category FROM ",
        _db_name,
        ".contact"
        );
      PREPARE stmt FROM @s;
      EXECUTE stmt ;
      DEALLOCATE PREPARE stmt;
    END IF;

  END LOOP STARTLOOP;

  SELECT count(*) FROM _domains WHERE area='personal' INTO @personal; 
  SELECT count(*) FROM _domains WHERE area='share' INTO @share; 
  SELECT count(*) FROM _domains WHERE area='private' INTO @team; 

  SELECT count(*) FROM _chats INTO @chats; 
  SELECT count(*) FROM _contacts INTO @contacts; 

  SELECT sum(filesize), count(*) FROM _files WHERE category NOT IN ('hub', 'folder') 
    INTO @filesize, @files_count;

  SELECT count(*) FROM _files WHERE category NOT IN ('hub', 'folder') AND user_filename 
    NOT IN('__trash__', '__chat__', '__send__', '__receive__', '__upload__')
    INTO @folders_count;

  SELECT user_filename, count(*) count FROM _files WHERE category IN ('folder') AND user_filename 
    NOT IN('__trash__', '__chat__', '__send__', '__receive__', '__upload__') 
    GROUP BY user_filename ORDER BY count DESC LIMIT 20;

  SELECT extension, count(*) count FROM _files WHERE category NOT IN ('hub', 'folder') 
    GROUP BY extension ORDER BY count DESC LIMIT 20;

  DROP TABLE IF EXISTS _uploads;
  CREATE TEMPORARY TABLE _uploads AS 
    SELECT s.uid, count(*) count, max(timestamp) ctime
      FROM mfs_changelog s INNER JOIN _domains d ON s.uid=d.hub_id
      WHERE event='media.new' GROUP BY uid;

  SELECT count(*) FROM _uploads INTO @active_users;
  SELECT 
    @personal personal, 
    @active_users active_users, 
    @share share, 
    @team team, 
    @chats chats, 
    @contacts contacts, 
    @filesize filesize, 
    @files_count files_count;

  SELECT email, count,  FROM_UNIXTIME(ctime, '%Y/%m/%d : %H:%i') date 
    FROM drumate d INNER JOIN _uploads u ON uid=id ORDER BY count DESC LIMIT 30;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `domain_exists` */;
