CREATE PROCEDURE `domain_user_role`(
  IN _domain_id INT(10),
  IN _uid VARCHAR(16)
)
BEGIN
  SELECT
    r.id role_id,
    r.name role_name 
  FROM 
  map_role mr 
  INNER JOIN role r ON r.id = mr.role_id 
  WHERE  
  r.domain_id =  _domain_id  AND 
  mr.uid =_uid;

END ;;
