)
BEGIN
  DECLARE _id VARBINARY(16);
  SELECT id FROM entity WHERE ident=_key OR id=_key INTO _id;
  UPDATE drumate SET `profile`=JSON_SET(`profile`,'$.lang', _lang) where id=_id;
