CREATE PROCEDURE `emailing`(
  IN _batch_size INT,
  IN _type VARCHAR(12)
)
BEGIN
  DROP TABLE IF EXISTS _emailing;
  CREATE TEMPORARY TABLE _emailing LIKE emailing;
  
  IF _type = 'gmail' THEN
    INSERT INTO _emailing SELECT * FROM emailing WHERE status='new' AND email LIKE "%@gmail.com"
      AND email NOT IN(SELECT email FROM drumate) ORDER BY rand() LIMIT _batch_size;
  ELSEIF _type = 'others' THEN
    INSERT INTO _emailing SELECT * FROM emailing WHERE status='new' AND email NOT LIKE "%@gmail.com"
      AND email NOT IN(SELECT email FROM drumate) ORDER BY rand() LIMIT _batch_size;
  ELSE
    INSERT INTO _emailing SELECT * FROM emailing WHERE status='new' 
      AND email NOT IN(SELECT email FROM drumate) ORDER BY rand() LIMIT _batch_size;
  END IF;
  INSERT  IGNORE INTO _emailing SELECT * FROM emailing_cc WHERE status='check';
  SELECT * FROM _emailing;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
