CREATE PROCEDURE `emailing_hit`(
  IN _args JSON
)
BEGIN
  DECLARE _range bigint;
  DECLARE _offset bigint;
  DECLARE _column VARCHAR(20) DEFAULT 'name';
  DECLARE _order VARCHAR(20) DEFAULT 'asc';
  DECLARE _type VARCHAR(20) DEFAULT NULL;
  DECLARE _domain VARCHAR(20) DEFAULT NULL;
  DECLARE _page INTEGER DEFAULT 1;

  SELECT IFNULL(JSON_VALUE(_args, "$.column"), 'ctime') INTO _column;
  SELECT IFNULL(JSON_VALUE(_args, "$.order"), 'desc') INTO _order;
  SELECT IFNULL(JSON_VALUE(_args, "$.page"), 1) INTO _page;
  SELECT IFNULL(JSON_VALUE(_args, "$.pagelength"), 45) INTO @rows_per_page;
  SELECT JSON_VALUE(_args, "$.type") INTO _type;
  SELECT JSON_VALUE(_args, "$.domain") INTO _domain;
  
  CALL pageToLimits(_page, _offset, _range);
  SET @p="/campaign-2026/logo-120.png";
  SELECT JSON_VALUE(headers, "$.source") source, s.ctime 
    FROM services_log s INNER JOIN emailing e ON FROM_BASE64(JSON_VALUE(headers, "$.source"))=e.email 
    WHERE s.name='/-/' AND JSON_VALUE(headers,  "$.service")='page.index' GROUP BY source
    ORDER BY
      CASE WHEN LCASE(_column) = 'date' AND LCASE(_order) = 'asc' THEN s.ctime END ASC,
      CASE WHEN LCASE(_column) = 'date' AND LCASE(_order) = 'desc' THEN s.ctime END DESC,
      CASE WHEN LCASE(_column) = 'email' AND LCASE(_order) = 'asc' THEN e.email END ASC,
      CASE WHEN LCASE(_column) = 'email' AND LCASE(_order) = 'desc' THEN e.email END DESC
    LIMIT _offset, _range;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
