/*!50003 DROP PROCEDURE IF EXISTS `member_list_workspaces` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `member_list_workspaces`(
  IN _uid VARCHAR(16),
  IN _dom_id INT
)
BEGIN
  DECLARE _db_name VARCHAR(255) CHARACTER SET ascii;

  SELECT db_name FROM entity WHERE id = _uid INTO _db_name;

  IF _db_name IS NULL THEN
    SELECT NULL AS hub_id, NULL AS hub_name, NULL AS area, NULL AS permission LIMIT 0;
  ELSE
    
    
    
    
    
    
    SET @sql = CONCAT(
      'SELECT e.id AS hub_id, ',
      '       IFNULL(IFNULL(e.ident, h.name), h.hubname) AS hub_name, ',
      '       e.area AS area, ',
      '       e.mtime AS mtime, ',
      '       du.size AS storage_size, ',
      '       p.permission ',
      'FROM `', _db_name, '`.permission p ',
      'INNER JOIN yp.entity e ON e.id = p.resource_id ',
      'LEFT JOIN yp.hub h ON h.id = e.id ',
      'LEFT JOIN yp.disk_usage du ON du.hub_id = e.id ',
      'WHERE p.entity_id = ', QUOTE(_uid),
      ' AND p.resource_id != \'*\' ',
      ' AND (p.expiry_time = 0 OR p.expiry_time > UNIX_TIMESTAMP()) ',
      ' AND e.type = \'hub\' ',
      ' AND e.dom_id = ', _dom_id,
      ' AND e.status = \'active\' ',
      ' ORDER BY e.ident ASC, e.id ASC'
    );
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `member_save_workspace_roles` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `member_save_workspace_roles`(
  IN _uid VARCHAR(16),
  IN _assignments LONGTEXT
  
)
BEGIN
  DECLARE _hub_id VARCHAR(16);
  DECLARE _priv_val TINYINT(4) UNSIGNED;
  DECLARE _hub_db VARCHAR(80);
  DECLARE _stmt TEXT;
  DECLARE done INT DEFAULT FALSE;

  DECLARE cur CURSOR FOR
    SELECT hub_id, privilege
    FROM JSON_TABLE(
      _assignments,
      '$[*]' COLUMNS(
        hub_id VARCHAR(16) PATH '$.hub_id',
        privilege TINYINT(4) UNSIGNED PATH '$.privilege'
      )
    ) AS jt;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

  OPEN cur;
  assign_loop: LOOP
    FETCH cur INTO _hub_id, _priv_val;
    IF done THEN LEAVE assign_loop; END IF;

    SELECT db_name INTO _hub_db
    FROM yp.entity
    WHERE id = _hub_id;

    IF _hub_db IS NOT NULL THEN
      
      
      SET _stmt = CONCAT(
        'CALL `', _hub_db, '`.permission_grant(',
          QUOTE('*'), ', ',
          QUOTE(_uid), ', ',
          '0, ',
          _priv_val, ', ',
          QUOTE('system'), ', ',
          QUOTE(''), ')'
      );
      PREPARE s FROM _stmt;
      EXECUTE s;
      DEALLOCATE PREPARE s;
    END IF;
  END LOOP;
  CLOSE cur;

  SELECT 0 AS failed;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `member_seen_by` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `member_seen_by`(
  IN _uid VARCHAR(16),
  IN _hubs JSON,
  IN _roles JSON
)
BEGIN
 DECLARE _idx INTEGER DEFAULT 0;
 DECLARE _hub_id VARCHAR(16);
 DECLARE _role_id  INTEGER;
 DECLARE _length INTEGER DEFAULT 0;
 

 SELECT  JSON_LENGTH(_hubs)  INTO _length;

  WHILE _idx < _length  DO 
    SELECT JSON_UNQUOTE(JSON_EXTRACT(_hubs, CONCAT("$[", _idx, "]"))) INTO _hub_id;
    INSERT INTO contact_sync(hub_id,uid,status) 
    SELECT _hub_id,_uid,'new' ON DUPLICATE KEY UPDATE status =status;
    SELECT _idx + 1 INTO _idx;
  END WHILE;

  SELECT 0 INTO _length;

  SELECT  JSON_LENGTH(_roles)  INTO _length;

  WHILE _idx < _length  DO 
    SELECT JSON_UNQUOTE(JSON_EXTRACT(_roles, CONCAT("$[", _idx, "]"))) INTO _role_id;
    INSERT INTO contact_sync(hub_id,uid,status) 
    SELECT uid,_uid,'new' map_role  WHERE  role_id = _role_id ON DUPLICATE KEY UPDATE status =status;
    SELECT _idx + 1 INTO _idx;
  END WHILE;


  SELECT * FROM contact_sync;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
