/*!50003 DROP PROCEDURE IF EXISTS `mfs_add_autorized_node` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_add_autorized_node`(
  IN _args JSON
)
BEGIN
  DECLARE _sessionKey VARCHAR(264) CHARACTER SET ascii;
  DECLARE _hub_id VARCHAR(16) CHARACTER SET ascii;
  DECLARE _nid VARCHAR(16) CHARACTER SET ascii;
  DECLARE _uid VARCHAR(16) CHARACTER SET ascii;
  DECLARE _expiry INT UNSIGNED;

  SELECT JSON_VALUE(_args, "$.sessionKey") INTO _sessionKey;
  SELECT JSON_VALUE(_args, "$.hub_id") INTO _hub_id;
  SELECT JSON_VALUE(_args, "$.nid") INTO _nid;
  SELECT JSON_VALUE(_args, "$.uid") INTO _uid;
  SELECT JSON_VALUE(_args, "$.expiry") INTO _expiry;

  IF _expiry IS NULL THEN 
    SELECT 0 INTO _expiry;
  END IF;

  IF _expiry > 0 THEN 
    SELECT UNIX_TIMESTAMP() + _expiry INTO _expiry;
  END IF;

  IF _sessionKey IS NOT NULL THEN
    INSERT INTO mfs_authorized_node (
      sessionKey,
      hub_id,
      nid,
      uid,
      expiry,
      ctime
    ) VALUES (
      _sessionKey,
      _hub_id,
      _nid,
      _uid,
      _expiry,
      UNIX_TIMESTAMP()
    )
    ON DUPLICATE KEY UPDATE expiry = _expiry;
  END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `mfs_cleanup_autorized_node` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_cleanup_autorized_node`(
)
BEGIN
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1 
      @sqlstate = RETURNED_SQLSTATE, 
      @errno = MYSQL_ERRNO, 
      @message = MESSAGE_TEXT;
  END;
  DELETE FROM mfs_authorized_node WHERE expiry< unix_timestamp();
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `mfs_get_autorized_node` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `mfs_get_autorized_node`(
  IN _sessionKey VARCHAR(64) CHARACTER SET ascii
)
BEGIN
  DECLARE _db_name VARCHAR(264) CHARACTER SET ascii;
  DECLARE _hub_id VARCHAR(16) CHARACTER SET ascii;
  DECLARE _nid VARCHAR(16) CHARACTER SET ascii;
  DECLARE _uid VARCHAR(16) CHARACTER SET ascii;
  DECLARE _expiry INT UNSIGNED;

  SELECT expiry, nid, uid, db_name 
    FROM mfs_authorized_node n INNER JOIN entity e ON e.id=n.hub_id 
    WHERE sessionKey=_sessionKey INTO _expiry, _nid, _uid, _db_name;
  IF _db_name IS NOT NULL AND (_expiry=0 OR UNIX_TIMESTAMP()<_expiry) THEN 
    SET @s = CONCAT("CALL ", _db_name, ".mfs_access_node(?, ?)");
    PREPARE stmt FROM @s;
    EXECUTE stmt USING _uid, _nid;
    DEALLOCATE PREPARE stmt;
    SELECT _uid uid, _db_name db_name;
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
