CREATE PROCEDURE `my_organisationx`(
   IN _uid VARCHAR(16) 
)
BEGIN
 EXPLAIN  SELECT
    r.*,
    p.privilege
  FROM 
    privilege p
  INNER JOIN organisation r ON r.domain_id = p.domain_id 
  
  WHERE p.domain_id <> 1 AND p.uid = _uid; 
END ;;
