CREATE PROCEDURE `secure_share_get_access_grant`(
  IN _token_id VARCHAR(80),
  IN _email    VARCHAR(512)
)
BEGIN
  SELECT granted_level, token_id, requester_email
  FROM   `secure_share_access_request`
  WHERE  token_id        = _token_id
    AND  requester_email = LOWER(TRIM(_email))
    AND  status          = 'approved'
  ORDER BY responded_at DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_increment_attempts` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_increment_attempts`(
  IN _token VARCHAR(80)
)
BEGIN
  DECLARE _cur TINYINT UNSIGNED DEFAULT 0;

  SELECT failed_attempts INTO _cur
  FROM `secure_share_token`
  WHERE id = _token
  LIMIT 1;

  UPDATE `secure_share_token`
  SET
    failed_attempts = _cur + 1,
    locked_at = IF(_cur + 1 >= 3, UNIX_TIMESTAMP(), locked_at)
  WHERE id = _token;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_info` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_info`(
  IN _token VARCHAR(80)
)
BEGIN
  DECLARE _hub_id            VARCHAR(16) CHARACTER SET ascii;
  DECLARE _node_id           VARCHAR(16) CHARACTER SET ascii;
  DECLARE _creator_id        VARCHAR(16) CHARACTER SET ascii;
  DECLARE _revoked_at        INT(11)     DEFAULT NULL;
  DECLARE _expiry_time       INT         DEFAULT 0;
  DECLARE _db_name           VARCHAR(50);
  DECLARE _fullname          VARCHAR(150);
  DECLARE _hub_name          VARCHAR(150);

  SELECT
    s.hub_id,
    s.node_id,
    s.creator_id,
    s.revoked_at,
    s.expiry_time
  INTO
    _hub_id, _node_id, _creator_id, _revoked_at, _expiry_time
  FROM `secure_share_token` s
  WHERE s.id = _token
  LIMIT 1;

  IF _hub_id IS NULL THEN
    SELECT 1 AS failed, 'TICKET_INVALID' AS validity;
  ELSE
    SELECT db_name FROM entity WHERE id = _hub_id INTO _db_name;

    SELECT CONCAT(firstname, ' ', IFNULL(lastname, ''))
    FROM   drumate
    WHERE  id = _creator_id
    INTO   _fullname;

    SELECT name FROM hub WHERE id = _hub_id INTO _hub_name;

    SELECT
      s.sys_id,
      s.id                AS token,
      s.hub_id,
      s.node_id,
      s.node_id           AS nid,
      s.creator_id,
      s.creator_id        AS sender_id,
      s.permission_level,
      
      
      IFNULL(
        s.capabilities,
        CASE s.permission_level
          WHEN 'can_view'     THEN JSON_ARRAY()
          ELSE JSON_ARRAY(s.permission_level)
        END
      )                   AS capabilities,
      s.recipient_email,
      s.domain_restriction,
      s.allowed_emails,
      s.password_hash,
      s.notify_on_open,
      s.expiry_time,
      s.access_count,
      s.last_accessed,
      s.failed_attempts,
      s.locked_at,
      s.ctime,
      _db_name            AS db_name,
      _fullname           AS `name`,
      _fullname           AS `sender`,
      _hub_name           AS title,
      IF(s.password_hash IS NOT NULL, 1, 0) AS require_password,
      IF(s.require_email = 1 OR (s.allowed_emails IS NOT NULL AND JSON_LENGTH(s.allowed_emails) > 0), 1, 0) AS require_email,
      IF(s.locked_at IS NOT NULL, 1, 0) AS is_locked,
      0                   AS is_public,
      1                   AS is_secure,
      CASE
        WHEN _revoked_at IS NOT NULL                                THEN 'TICKET_REVOKED'
        WHEN _expiry_time > 0 AND UNIX_TIMESTAMP() > _expiry_time  THEN 'TICKET_EXPIRED'
        ELSE 'TICKET_OK'
      END                 AS validity
    FROM `secure_share_token` s
    WHERE s.id = _token;
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_list` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_list`(
  IN _hub_id     VARCHAR(16) CHARACTER SET ascii,
  IN _node_id    VARCHAR(16) CHARACTER SET ascii,
  IN _creator_id VARCHAR(16) CHARACTER SET ascii
)
BEGIN
  SELECT
    s.sys_id,
    s.id,
    s.hub_id,
    s.node_id,
    s.creator_id,
    s.permission_level,
    IFNULL(
      s.capabilities,
      CASE s.permission_level
        WHEN 'can_view'     THEN JSON_ARRAY()
        ELSE JSON_ARRAY(s.permission_level)
      END
    )                   AS capabilities,
    s.recipient_email,
    s.domain_restriction,
    s.allowed_emails,
    s.expiry_time,
    s.revoked_at,
    s.access_count,
    s.last_accessed,
    s.ctime,
    CASE
      WHEN s.revoked_at IS NOT NULL                               THEN 'revoked'
      WHEN s.expiry_time > 0 AND UNIX_TIMESTAMP() > s.expiry_time THEN 'expired'
      ELSE 'active'
    END AS `status`
  FROM  `secure_share_token` s
  WHERE  s.hub_id     = _hub_id
    AND  s.node_id    = _node_id
    AND  s.creator_id = _creator_id
  ORDER BY s.ctime DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_list_access_events` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_list_access_events`(
  IN _hub_id     VARCHAR(16) CHARACTER SET ascii,
  IN _node_id    VARCHAR(16) CHARACTER SET ascii,
  IN _creator_id VARCHAR(16) CHARACTER SET ascii
)
BEGIN
  SELECT
    e.sys_id          AS id,
    e.token_id,
    e.recipient_email,
    e.actor_id,
    e.entered_at,
    e.last_seen_at,
    (e.last_seen_at - e.entered_at) AS duration
  FROM  `secure_share_access_event` e
  JOIN  `secure_share_token` t ON t.id = e.token_id
  WHERE t.hub_id     = _hub_id
    AND t.node_id    = _node_id
    AND t.creator_id = _creator_id
    
    
    
    AND (t.require_email = 1 OR t.recipient_email IS NOT NULL OR t.password_hash IS NOT NULL)
  ORDER BY e.last_seen_at DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_list_open_notifications` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_list_open_notifications`(
  IN _creator_id VARCHAR(16) CHARACTER SET ascii
)
BEGIN
  
  
  
  
  SELECT
    MAX(e.sys_id)       AS id,
    e.token_id,
    e.hub_id,
    e.node_id,
    e.recipient_email,
    MAX(e.last_seen_at) AS last_seen_at
  FROM  `secure_share_access_event` e
  JOIN  `secure_share_token` t ON t.id = e.token_id
  WHERE t.creator_id     = _creator_id
    AND t.notify_on_open != 0
    AND (e.actor_id IS NULL OR e.actor_id != _creator_id)
    AND e.last_seen_at >= (UNIX_TIMESTAMP() - 604800)
  GROUP BY e.token_id, e.hub_id, e.node_id, e.recipient_email
  ORDER BY last_seen_at DESC
  LIMIT 50;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_list_requests` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_list_requests`(
  IN _creator_id VARCHAR(16)
)
BEGIN
  
  
  
  
  SELECT
    r.id              AS request_id,
    r.token_id,
    r.hub_id,
    r.node_id,
    r.requester_email,
    r.requested_level,
    r.message,
    r.status,
    r.ctime,
    h.name            AS workspace_name
  FROM `secure_share_access_request` r
  LEFT JOIN `hub` h ON h.id = r.hub_id
  WHERE r.creator_id = _creator_id
    AND r.status     = 'pending'
  ORDER BY r.ctime DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_log_access_event` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_log_access_event`(
  IN _token     VARCHAR(80),
  IN _email     VARCHAR(512),
  IN _actor_id  VARCHAR(16) CHARACTER SET ascii,
  IN _socket_id VARCHAR(32)
)
BEGIN
  DECLARE _hub_id   VARCHAR(16) CHARACTER SET ascii;
  DECLARE _node_id  VARCHAR(16) CHARACTER SET ascii;
  DECLARE _tok_mail VARCHAR(512);
  DECLARE _mail     VARCHAR(512);
  DECLARE _sock     VARCHAR(32);
  DECLARE _now      INT DEFAULT 0;
  DECLARE _existing INT DEFAULT 0;

  SET _now = UNIX_TIMESTAMP();

  SELECT hub_id, node_id, recipient_email
  INTO   _hub_id, _node_id, _tok_mail
  FROM   `secure_share_token`
  WHERE  id = _token
  LIMIT  1;

  SET _mail = NULLIF(TRIM(IFNULL(_email, '')), '');
  IF _mail IS NULL THEN
    SET _mail = _tok_mail;
  END IF;

  SET _sock = NULLIF(TRIM(IFNULL(_socket_id, '')), '');

  
  
  
  
  IF _hub_id IS NOT NULL THEN
    SET _existing = 0;

    IF _sock IS NOT NULL THEN
      SELECT sys_id INTO _existing
      FROM   `secure_share_access_event`
      WHERE  token_id = _token AND socket_id = _sock
      ORDER BY sys_id DESC
      LIMIT  1;
    ELSEIF _actor_id IS NOT NULL THEN
      SELECT sys_id INTO _existing
      FROM   `secure_share_access_event`
      WHERE  token_id = _token AND actor_id = _actor_id AND socket_id IS NULL
      ORDER BY sys_id DESC
      LIMIT  1;
    ELSEIF _mail IS NOT NULL THEN
      SELECT sys_id INTO _existing
      FROM   `secure_share_access_event`
      WHERE  token_id = _token AND recipient_email = _mail AND actor_id IS NULL AND socket_id IS NULL
      ORDER BY sys_id DESC
      LIMIT  1;
    END IF;

    IF _existing > 0 THEN
      UPDATE `secure_share_access_event`
      SET    last_seen_at    = _now,
             recipient_email = IFNULL(_mail, recipient_email),
             actor_id        = IFNULL(_actor_id, actor_id)
      WHERE  sys_id = _existing;
    ELSE
      INSERT INTO `secure_share_access_event`
        (token_id, hub_id, node_id, recipient_email, actor_id, socket_id, entered_at, last_seen_at)
      VALUES
        (_token, _hub_id, _node_id, _mail, _actor_id, _sock, _now, _now);
    END IF;
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_respond_to_access_request` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_respond_to_access_request`(
  IN _request_id    VARCHAR(16),
  IN _responder_id  VARCHAR(16),
  IN _action        VARCHAR(8),
  IN _granted_level VARCHAR(20)
)
BEGIN
  DECLARE _creator_id    VARCHAR(16) CHARACTER SET ascii;
  DECLARE _req_status    VARCHAR(10);
  DECLARE _active_socket VARCHAR(32);

  SELECT r.creator_id, r.status
  INTO   _creator_id, _req_status
  FROM   `secure_share_access_request` r
  WHERE  r.id = _request_id
  LIMIT  1;

  IF _creator_id IS NULL THEN
    SELECT NULL AS id, 'NOT_FOUND' AS error;
  ELSEIF _req_status != 'pending' THEN
    SELECT NULL AS id, 'ALREADY_RESPONDED' AS error;
  ELSEIF _creator_id != _responder_id THEN
    SELECT NULL AS id, 'FORBIDDEN' AS error;
  ELSE
    UPDATE `secure_share_access_request`
    SET
      status        = IF(_action = 'approve', 'approved', 'denied'),
      granted_level = IF(_action = 'approve', _granted_level, NULL),
      responded_at  = UNIX_TIMESTAMP()
    WHERE id = _request_id;

    
    SELECT t.active_socket_id INTO _active_socket
    FROM   `secure_share_access_request` r
    JOIN   `secure_share_token` t ON t.id = r.token_id
    WHERE  r.id = _request_id
    LIMIT  1;

    SELECT r.id, r.token_id, r.hub_id, r.node_id, r.creator_id,
           r.requester_email, r.requested_level, r.granted_level,
           r.status, r.responded_at,
           _active_socket AS guest_socket_id
    FROM   `secure_share_access_request` r
    WHERE  r.id = _request_id;
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `secure_share_revoke` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `secure_share_revoke`(
  IN _token      VARCHAR(80),
  IN _creator_id VARCHAR(16) CHARACTER SET ascii
)
BEGIN
  UPDATE `secure_share_token`
  SET    revoked_at = UNIX_TIMESTAMP()
  WHERE  id         = _token
    AND  creator_id = _creator_id
    AND  revoked_at IS NULL;

  
  
  SELECT
    s.sys_id,
    s.id,
    s.hub_id,
    s.node_id,
    s.creator_id,
    s.recipient_email,
    s.revoked_at,
    s.access_count,
    s.last_accessed,
    s.active_socket_id
  FROM `secure_share_token` s
  WHERE  s.id         = _token
    AND  s.creator_id = _creator_id
    AND  s.revoked_at IS NOT NULL;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `seen_by` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `seen_by`(
  IN _org_id VARCHAR(16),
  IN _uid VARCHAR(16),
  IN _option VARCHAR(16),
  IN _page INT(6)

)
BEGIN
  DECLARE _range bigint;
  DECLARE _offset bigint;
  
  CALL pageToLimits(_page, _offset, _range);
  IF _option = 'member' THEN
    SELECT 
      _page as `page`,
      o.id ogrid,
      o.name org_name,
      dm.id  domain_id,
      dm.name domain_name,
      d.id drumate_id,
      d.firstname,
      d.lastname,
      d.fullname,
      d.email,
      e.ident,
      read_json_object(d.profile, "address")  `address`,
      read_json_object(d.profile, "personaldata")  personaldata,
      read_json_object(d.profile, "mobile")  mobile,
      p.privilege, 
      CASE WHEN IFNULL(read_json_object(d.profile, "mobile_verified"),'no') <> 'yes' THEN 'no' ELSE 'yes' END  mobile_verified,
      CASE WHEN IFNULL(read_json_object(d.profile, "email_verified"),'no') <> 'yes' THEN 'no' ELSE 'yes' END  email_verified,  
      e.status,
      IFNULL(JSON_UNQUOTE(JSON_EXTRACT(e.settings, '$.status_date')),null) status_date,
      d.otp
    FROM 
      privilege p 
      INNER JOIN organisation o ON p.domain_id=o.domain_id  
      INNER JOIN domain dm ON  dm.id = p.domain_id  
      INNER JOIN drumate d ON p.uid = d.id 
      INNER JOIN entity e  ON d.id = e.id 
      INNER JOIN contact_sync cs ON hub_id = p.uid 
      WHERE  o.id =_org_id  AND   p.privilege <> 1  AND cs.uid = _uid 
      ORDER BY fullname ASC, d.id ASC
      LIMIT _offset, _range;
  ELSE 
    SELECT
      _page as `page`,
      r.id role_id,
      r.name role_name 
    FROM 
    map_role mr 
    INNER JOIN role r ON r.id = mr.role_id 
    WHERE  
      r.org_id =  _org_id  AND 
      mr.uid IN (SELECT hub_id FROM contact_sync WHERE uid = _uid)
      ORDER BY position ASC
      LIMIT _offset, _range;
  END IF;
      
END ;;
DELIMITER ;
