/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE PROCEDURE `session_logout_by_admin`(
  IN _uid VARCHAR(16)
 )
BEGIN
  DELETE FROM cookie  WHERE `uid`=_uid;
  DELETE FROM socket  WHERE `uid`=_uid;
END ;;
