  SELECT JSON_OBJECT("step","password") INTO _metadata ;  
  IF _method = 'b2bsignup' THEN 
  SELECT  JSON_OBJECT("step","company","mode","b2bsignup" ) INTO _metadata ;  
    
    SELECT 'signup' INTO _method; 
