CREATE PROCEDURE `token_get`(
  IN _secret      VARCHAR(512)
)
BEGIN

  SELECT t.*, d.email as inviter_email FROM 
  token t
  LEFT JOIN drumate d on d.id=t.inviter_id
  WHERE secret = _secret;

END ;;
