CREATE PROCEDURE `tranfer_token_get`(
  IN _secret      VARCHAR(512)
)
BEGIN

  
  SELECT 
   t.email,t.name,t.secret,t.status,t.ctime,t.metadata
  FROM 
  tranfer_token t
  WHERE t.secret = _secret;

END ;;
