CREATE PROCEDURE `user_change_status`(
  IN _key VARCHAR(128),
  IN _status VARCHAR(16)
)
BEGIN
  UPDATE entity SET status=_status WHERE id=_key OR ident=_key;
  IF ROW_COUNT() THEN
    CALL get_user(_key);
  END IF;
END ;;
